    self.loader = CfUtils.FillEnentAnim(self.typeImg, self.point)
end

--选择
function UIMazeJoinBattleEventDialog:OnbtnOk()
    if not self.selectAssist then return end
    MazeMgr:GetInstance():MazeMoveToAssist(self.point, self.selectAssist, function( )
        self:Close()
    end)
end

--拒绝
function UIMazeJoinBattleEventDialog:OnbtnReject()
    GameUtils.SecondConfirm(localize("确定要拒绝同事的加入吗"), function(  )
        MazeMgr:GetInstance():MazeMoveToAssist(self.point, nil, function( )
            self:Close()
        end)
    end)
end

function UIMazeJoinBattleEventDialog:GetAllRoleCard()
    local cards = {}
    for k, v in pairs(self.assistants) do
        local assistRole = CfUtils.GetCfVo(AutoIds.IdSetting361, "MazeAssistRoleVo", v.id)
        if assistRole then
            assistRole.isAssistant = Constants.MazeRole.AssistRole
            assistRole.cardLevel = v.cardLevel
            assistRole.star = v.star
            table.insert(cards, assistRole)
        end
    end
    return cards
end

function UIMazeJoinBattleEventDialog:Close()
    MazeMgr:GetInstance():OpenMazeMainGameObject()
    UIModule.CloseDialog(self.controller)
end

function UIMazeJoinBattleEventDialog:SetTopCommon()
    CfUtils.RefreshTopCommon(function()
        self:Close()
    end)
end

